    """
    Insert K multiplication signs into num_str to get the maximum product.
    The multiplication signs must not be inserted at the beginning or end of the string,
    and they must not be next to each other.
    """
    if K == 0:
        return int(num_str)

    max_product = 0
    for i in range(N - K):
        product = 1
        for j in range(i, i + K + 1):
            product *= int(num_str[j])
        max_product = max(max_product, product)

    return max_product

